"use client";

import { useAuth } from "@/app/context/auth-context";
import { PERMISSIONS } from "@/lib/permissions";
import { useRouter, usePathname } from "next/navigation";
import Link from "next/link";
import { cn } from "@/lib/utils";
import {
  LayoutDashboard,
  Users,
  Settings,
  ParkingCircle,
  Calendar,
  Star,
  UserCog,
  KeyRound,
  UserRound,
  Car,
  Settings2,
} from "lucide-react";

const navigationItems = [
  {
    label: "Dashboard",
    href: "/dashboard",
    icon: LayoutDashboard,
    permission: PERMISSIONS.DASHBOARD_VIEW,
  },
  {
    label: "Staff Users",
    href: "/dashboard/users",
    icon: Users,
    permission: PERMISSIONS.USER_VIEW,
  },
  {
    label: "Parking Users",
    href: "/dashboard/parking-users",
    icon: UserCog,
    permission: PERMISSIONS.USER_VIEW,
  },
  {
    label: "Parkings",
    href: "/dashboard/parkings",
    icon: ParkingCircle,
    permission: PERMISSIONS.PARKING_VIEW,
  },
  {
    label: "Bookings",
    href: "/dashboard/bookings",
    icon: Calendar,
    permission: PERMISSIONS.BOOKING_VIEW,
  },
  {
    label: "Reviews",
    href: "/dashboard/reviews",
    icon: Star,
    permission: PERMISSIONS.DASHBOARD_VIEW, // Reviews don't have a specific permission yet, using dashboard view
  },
  {
    label: "Customers",
    href: "/dashboard/customers",
    icon: UserRound,
    permission: PERMISSIONS.CUSTOMER_VIEW,
  },
  {
    label: "Vehicles",
    href: "/dashboard/vehicles",
    icon: Car,
    permission: PERMISSIONS.VEHICLE_VIEW,
  },
  {
    label: "Password Reset",
    href: "/dashboard/forgot-password",
    icon: KeyRound,
    permission: PERMISSIONS.SETTINGS_RESET_PASSWORD,
  },
  {
    label: "Configurations",
    href: "/dashboard/configurations",
    icon: Settings2,
    permission: PERMISSIONS.CONFIGURATION_VIEW,
  },
  {
    label: "Settings",
    href: "/dashboard/settings",
    icon: Settings,
    permission: PERMISSIONS.SETTINGS_VIEW,
  },
];

interface SidebarProps {
  onItemClick?: () => void;
}

export function Sidebar({ onItemClick }: SidebarProps) {
  const { user, logout, canAccess, hasPermission } = useAuth();
  const router = useRouter();
  const pathname = usePathname();

  const handleLogout = () => {
    logout();
    router.push("/");
  };

  const filteredItems = navigationItems.filter((item) =>
    hasPermission(item.permission)
  );

  return (
    <div className="w-64 border-r border-border bg-sidebar flex flex-col h-full">
      {/* Logo */}
      <div className="h-20 flex items-center px-6 border-b border-sidebar-border">
        <Link href="/dashboard" className="flex items-center gap-3 group">
          <div className="flex items-center justify-center w-10 h-10 rounded-xl bg-primary text-primary-foreground shadow-sm shadow-primary/25 overflow-hidden flex-shrink-0">
            <img
              src="/login-brand.png"
              alt="Gelagle Park"
              className="w-full h-full object-cover"
            />
          </div>
          <div>
            <span className="font-bold text-lg tracking-tight text-sidebar-foreground group-hover:text-primary transition-colors block">
              Gelagle Park
            </span>
            {/* <p className="text-[10px] text-muted-foreground font-medium mt-0.5 pl-0.5">
              Dashboard
            </p> */}
          </div>
        </Link>
      </div>

      {/* Navigation */}
      <nav className="flex-1 px-4 py-8 space-y-2 overflow-y-auto">
        {filteredItems.map((item) => {
          const Icon = item.icon;
          const isActive = pathname === item.href;

          return (
            <button
              key={item.href}
              onClick={() => {
                router.push(item.href);
                onItemClick?.();
              }}
              className={cn(
                "w-full flex items-center gap-4 px-6 py-4 rounded-lg text-base font-medium transition-colors my-1",
                isActive
                  ? "bg-primary text-primary-foreground shadow-md"
                  : "text-sidebar-foreground hover:bg-sidebar-accent/50 hover:pl-7"
              )}
            >
              <Icon size={22} />
              {item.label}
            </button>
          );
        })}
      </nav>
    </div>
  );
}
